// Decide QUEM recebe e-mail e monta o corpo da mensagem.
//
// Regra de silêncio: empresa sem nada a reportar não recebe e-mail nenhum.
// Alerta que chega todo dia sem novidade vira ruído e o gestor para de ler —
// aí, quando o caixa realmente furar, ele não abre a mensagem.

const brl = (v) =>
  Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const dataBR = (d) => (d ? new Date(d + 'T12:00:00').toLocaleDateString('pt-BR') : '—');

const saida = [];

for (const item of $input.all()) {
  const t = item.json;

  const venceHoje = Number(t.vence_hoje_pagar || 0) + Number(t.vence_hoje_receber || 0);
  const atrasado = Number(t.atrasado_pagar || 0) + Number(t.atrasado_receber || 0);
  const temCaixaNegativo = Boolean(t.primeiro_dia_negativo);
  const temRecipiente = Array.isArray(t.recipients) && t.recipients.length > 0;

  const temAlgoARelatar = venceHoje > 0 || atrasado > 0 || temCaixaNegativo;
  if (!temAlgoARelatar || !temRecipiente) continue;

  // Severidade: caixa negativo é o único que merece 'critical'.
  const severity = temCaixaNegativo ? 'critical' : t.qtd_atrasados > 0 ? 'warning' : 'info';

  const linhas = (t.titulos || [])
    .map((x) => {
      const cor = x.situacao === 'atrasado' ? '#b91c1c' : '#1f2937';
      const sinal = x.type === 'receita' ? '+' : '−';
      return `<tr>
        <td style="padding:6px 10px;border-bottom:1px solid #eee;color:${cor}">${dataBR(x.due_date)}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #eee;color:${cor}">${x.description ?? ''}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #eee;color:${cor}">${x.entity_name ?? '—'}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right;color:${cor}">${sinal} ${brl(x.amount)}</td>
      </tr>`;
    })
    .join('');

  const blocoCaixa = temCaixaNegativo
    ? `<div style="background:#fef2f2;border-left:4px solid #dc2626;padding:12px 16px;margin:16px 0">
         <strong style="color:#991b1b">Atenção: seu caixa fica negativo em ${dataBR(t.primeiro_dia_negativo)}.</strong>
         <div style="color:#7f1d1d;font-size:14px;margin-top:4px">
           Considere antecipar recebimentos ou renegociar pagamentos antes dessa data.
         </div>
       </div>`
    : '';

  const html = `
<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px;margin:0 auto;color:#1f2937">
  <h2 style="margin:0 0 4px">Resumo financeiro — ${t.tenant_name}</h2>
  <div style="color:#6b7280;font-size:14px;margin-bottom:20px">${new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' })}</div>

  ${blocoCaixa}

  <table style="width:100%;border-collapse:collapse;margin-bottom:20px">
    <tr>
      <td style="padding:12px;background:#f9fafb;border-radius:6px">
        <div style="color:#6b7280;font-size:13px">Saldo em caixa hoje</div>
        <div style="font-size:22px;font-weight:600;color:${Number(t.saldo_atual) < 0 ? '#dc2626' : '#059669'}">${brl(t.saldo_atual)}</div>
      </td>
    </tr>
  </table>

  <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px">
    <tr><td style="padding:6px 0">A pagar hoje</td><td style="text-align:right;font-weight:600">${brl(t.vence_hoje_pagar)}</td></tr>
    <tr><td style="padding:6px 0">A receber hoje</td><td style="text-align:right;font-weight:600">${brl(t.vence_hoje_receber)}</td></tr>
    <tr><td style="padding:6px 0;color:#b91c1c">Contas atrasadas (${t.qtd_atrasados})</td><td style="text-align:right;font-weight:600;color:#b91c1c">${brl(t.atrasado_pagar)}</td></tr>
    <tr><td style="padding:6px 0;color:#b91c1c">Recebimentos atrasados</td><td style="text-align:right;font-weight:600;color:#b91c1c">${brl(t.atrasado_receber)}</td></tr>
  </table>

  ${linhas ? `<h3 style="font-size:15px;margin:0 0 8px">Títulos em aberto até hoje</h3>
  <table style="width:100%;border-collapse:collapse;font-size:13px">
    <thead><tr style="background:#f9fafb">
      <th style="padding:8px 10px;text-align:left">Vence</th>
      <th style="padding:8px 10px;text-align:left">Descrição</th>
      <th style="padding:8px 10px;text-align:left">Cliente/Fornecedor</th>
      <th style="padding:8px 10px;text-align:right">Valor</th>
    </tr></thead>
    <tbody>${linhas}</tbody>
  </table>` : ''}

  <div style="color:#9ca3af;font-size:12px;margin-top:24px;border-top:1px solid #eee;padding-top:12px">
    Enviado automaticamente pelo seu sistema financeiro.
  </div>
</div>`;

  const assunto = temCaixaNegativo
    ? `⚠️ ${t.tenant_name}: caixa negativo previsto para ${dataBR(t.primeiro_dia_negativo)}`
    : `Resumo financeiro — ${t.tenant_name}`;

  saida.push({
    json: {
      tenant_id: t.tenant_id,
      tenant_name: t.tenant_name,
      to: t.recipients.join(','),
      subject: assunto,
      html,
      severity,
      notification: {
        tenant_id: t.tenant_id,
        kind: 'digest_diario',
        title: temCaixaNegativo
          ? `Caixa negativo previsto para ${dataBR(t.primeiro_dia_negativo)}`
          : `${t.qtd_atrasados} conta(s) atrasada(s) e ${brl(t.vence_hoje_pagar)} a pagar hoje`,
        body: `Saldo atual ${brl(t.saldo_atual)}. A pagar hoje ${brl(t.vence_hoje_pagar)}, a receber ${brl(t.vence_hoje_receber)}.`,
        severity,
        link: '/contas-a-pagar?filtro=atrasado',
        meta: {
          saldo_atual: t.saldo_atual,
          qtd_atrasados: t.qtd_atrasados,
          primeiro_dia_negativo: t.primeiro_dia_negativo,
        },
      },
    },
  });
}

return saida;
